      hu: ["1870-ben építették francia misszionáriusok.", "Magassága körülbelül 3 méter.", "Helyi kőből készült.", "Atuona közelében, Hiva Oa szigetén található.", "Augusztus 15-én (Nagyboldogasszony ünnepe) körmenetet tartanak.", "Francia Polinézia katolikus örökségének része."],
      ro: ["Construită în 1870 de misionari francezi.", "Înălțime: aproximativ 3 metri.", "Realizată din piatră locală.", "Amplasată pe un deal lângă Atuona, insula Hiva Oa.", "Procesiuni anuale pe 15 august (Adormirea Maicii Domnului).", "Parte a patrimoniului catolic al Polineziei Franceze."],
      en: ["Erected in 1870 by French missionaries.", "Height: approximately 3 meters.", "Material: local stone.", "Located on a hill near Atuona, Hiva Oa, Marquesas Islands.", "Annual procession on August 15 (Assumption of Mary).", "Part of French Polynesia's Catholic heritage."],
      es: ["Erigida en 1870 por misioneros franceses.", "Altura: aprox. 3 metros.", "Material: piedra local.", "Ubicación: colina cerca de Atuona, Hiva Oa, Marquesas.", "Procesiones anuales el 15 de agosto (Asunción).", "Parte del patrimonio católico de la Polinesia Francesa."],
      pt: ["Erguida em 1870 por missionários franceses.", "Altura: aprox. 3 metros.", "Material: pedra local.", "Localização: colina perto de Atuona, Hiva Oa, Marquesas.", "Procissões anuais em 15 de agosto (Assunção).", "Parte do património católico da Polinésia Francesa."],
      fr: ["Érigée en 1870 par des missionnaires français.", "Hauteur : environ 3 mètres.", "Matériau : pierre locale.", "Lieu : colline près d'Atuona, Hiva Oa, Marquises.", "Processions annuelles le 15 août (Assomption).", "Fait partie du patrimoine catholique de la Polynésie française."],
